from abq_authoring import *
start(2021,'Miriam’s Crèche',5)
add('a','Outline, using examples, the different types of planning that contribute to the success of Miriam’s Crèche.',30,'business-2-13','types-of-business-plan',['Outline four different types of planning. Apply the two 8-mark allocations to the stronger responses and 7 marks to each of the other two.'],[response(i,f'Type of planning {i} · {sum(m)} marks',[('name','Type of planning',m[0]),('explain','Explain',m[1]),('link','Link',m[2])]) for i,m in enumerate([[3,3,2],[3,3,2],[2,3,2],[2,3,2]],1)],[21,22])
add('b-i','Discuss, with reference to the text, the types of business insurance you would recommend for Miriam’s Crèche.',18,'business-3-17','types-of-business-insurance',['The scheme awards 3 responses at 6 marks each.'],[response(i,f'Type of insurance {i}',[('name','State',2),('explain','Developed explanation',2),('link','Link',2)]) for i in [1,2,3]],[23,24])
add('b-ii','Describe two types of taxation Miriam’s Crèche might pay.',12,'business-3-18','business-taxation',['The scheme awards 2 responses at 6 marks each. Use relevant evidence from Miriam’s Crèche for each type of tax.'],[response(i,f'Type of tax {i}',[('name','Type of tax',2),('explain','Describe',2),('link','Link',2)]) for i in [1,2]],[24,25])
add('c','Evaluate the price and promotion element of the marketing mix for Miriam’s Crèche.',20,'business-4-17','price-and-promotion',['Evaluate both price and promotion. Each element carries 10 marks.','An overall evaluation at the end can earn the 4 evaluation marks if it addresses both elements. Assign those marks to the two evaluation rows below; do not count the same evaluation twice.'],[response(i,label,[('explain','Explanation',3),('develop','Point of development',3),('link','Link',2),('evaluate','Evaluation',2)]) for i,label in enumerate(['Price','Promotion'],1)],[25,26])
finish({'A':30,'B(i)':18,'B(ii)':12,'C':20},[21,22,23,24,25,26],'No finite answer menu is printed. Planning, insurance and tax methods in the scheme are open examples. Price and promotion in C are required headings within one response, not alternatives; keep them together with their published component allocations.', ['B splits at the published 18/12 boundary.','The scheme permits an overall evaluation in C but requires evaluation of both named marketing elements.','The existing planning and insurance cards keep their IDs; their canonical topics are corrected from sources of finance/international trade to planning/insurance.','PDF page numbers are one greater than printed numbers in this scheme.'])
